-- One-off bootstrap: create the first invite code. Run manually in the Supabase SQL editor.
--
-- Until the invite admin screen exists (MVA-141), invites are created here. The code is
-- generated by the database and shown in the result grid when you run this. Copy it, use it at
-- /join on the app, and never paste a real code into the repo.
--
-- Use this for members other than the initial admin (that account needs no invite).
--
-- Change the tier name to 'Prospect' or 'Contractor' if needed; only those three are allowed.

insert into public.invites (tier_id, note)
select id, 'first invite'
from public.tiers
where name = 'Recruit'
returning code, expires_at;
